APP_QSS = '/* Light slate + teal TaskManager theme */\n\nQWidget {\n    background-color: #f1f5f9;\n    color: #0f172a;\n    font-size: 13px;\n}\n\nQMainWindow, QDialog {\n    background-color: #f1f5f9;\n}\n\nQToolBar {\n    background-color: #0f766e;\n    border: none;\n    spacing: 6px;\n    padding: 6px 8px;\n}\n\nQToolBar QToolButton {\n    background-color: transparent;\n    color: #ecfdf5;\n    border: none;\n    border-radius: 4px;\n    padding: 6px 10px;\n}\n\nQToolBar QToolButton:hover {\n    background-color: #14b8a6;\n}\n\nQToolBar QToolButton:pressed {\n    background-color: #0d9488;\n}\n\nQToolBar QToolButton:checked {\n    background-color: #0f766e;\n    color: #ecfdf5;\n}\n\nQToolBar QToolButton:checked:hover {\n    background-color: #14b8a6;\n}\n\nQLineEdit, QSpinBox, QDateEdit, QComboBox, QPlainTextEdit, QTextEdit {\n    background-color: #ffffff;\n    border: 1px solid #cbd5e1;\n    border-radius: 4px;\n    padding: 4px 8px;\n    selection-background-color: #99f6e4;\n}\n\nQLineEdit:focus, QComboBox:focus, QDateEdit:focus, QPlainTextEdit:focus {\n    border: 1px solid #0d9488;\n}\n\nQPushButton {\n    background-color: #0d9488;\n    color: #ffffff;\n    border: none;\n    border-radius: 4px;\n    padding: 6px 14px;\n}\n\nQPushButton:hover {\n    background-color: #0f766e;\n}\n\nQPushButton:pressed {\n    background-color: #115e59;\n}\n\nQPushButton:disabled {\n    background-color: #94a3b8;\n}\n\nQPushButton#secondaryButton {\n    background-color: #e2e8f0;\n    color: #0f172a;\n}\n\nQPushButton#secondaryButton:hover {\n    background-color: #cbd5e1;\n}\n\nQTabWidget::pane {\n    border: 1px solid #cbd5e1;\n    background-color: #ffffff;\n    border-radius: 4px;\n}\n\nQTabBar::tab {\n    background-color: #e2e8f0;\n    color: #334155;\n    padding: 8px 16px;\n    margin-right: 2px;\n    border-top-left-radius: 4px;\n    border-top-right-radius: 4px;\n}\n\nQTabBar::tab:selected {\n    background-color: #ffffff;\n    color: #0f766e;\n    font-weight: 600;\n}\n\nQTabBar::tab:hover:!selected {\n    background-color: #ccfbf1;\n}\n\nQTableWidget {\n    background-color: #ffffff;\n    alternate-background-color: #f8fafc;\n    gridline-color: #e2e8f0;\n    border: none;\n    selection-background-color: #99f6e4;\n    selection-color: #0f172a;\n}\n\nQHeaderView::section {\n    background-color: #e2e8f0;\n    color: #334155;\n    padding: 6px 8px;\n    border: none;\n    border-right: 1px solid #cbd5e1;\n    border-bottom: 1px solid #cbd5e1;\n    font-weight: 600;\n}\n\nQMenu {\n    background-color: #ffffff;\n    border: 1px solid #cbd5e1;\n}\n\nQMenu::item:selected {\n    background-color: #ccfbf1;\n    color: #0f172a;\n}\n\nQStatusBar {\n    background-color: #e2e8f0;\n    color: #475569;\n}\n\nQCheckBox::indicator:checked {\n    background-color: #0d9488;\n    border: 1px solid #0f766e;\n}\n\nQCheckBox:disabled {\n    color: #94a3b8;\n}\n\nQCheckBox::indicator:disabled {\n    background-color: #e2e8f0;\n    border: 1px solid #cbd5e1;\n}\n\nQCheckBox::indicator:checked:disabled {\n    background-color: #99f6e4;\n    border: 1px solid #94a3b8;\n}\n\nQListWidget {\n    background-color: #ffffff;\n    border: 1px solid #cbd5e1;\n    border-radius: 4px;\n    outline: none;\n}\n\nQListWidget::item:disabled {\n    color: #94a3b8;\n}\n\nQProgressBar {\n    background-color: #e2e8f0;\n    border: 1px solid #cbd5e1;\n    border-radius: 4px;\n    text-align: center;\n    color: #0f172a;\n}\n\nQProgressBar::chunk {\n    background-color: #0d9488;\n}\n\nQGroupBox {\n    border: 1px solid #cbd5e1;\n    border-radius: 4px;\n    margin-top: 10px;\n    padding-top: 8px;\n    background-color: #ffffff;\n}\n\nQGroupBox::title {\n    subcontrol-origin: margin;\n    left: 10px;\n    padding: 0 4px;\n    color: #0f766e;\n}\n'

